function sub(a, b) { return [a[0] - b[0], a[1] - b[1], a[2] - b[2]]; }
function cross(a, b) {
  return [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
}
function dot(a, b) { return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]; }

function createCube(size) {
  var s = (typeof size === 'number' && isFinite(size) && size > 0) ? size : 1;
  var vertices = [
    [0, 0, 0], [s, 0, 0], [s, s, 0], [0, s, 0],
    [0, 0, s], [s, 0, s], [s, s, s], [0, s, s]
  ];
  var faces = [
    [4, 5, 6], [4, 6, 7],
    [1, 0, 3], [1, 3, 2],
    [5, 1, 2], [5, 2, 6],
    [0, 4, 7], [0, 7, 3],
    [7, 6, 2], [7, 2, 3],
    [0, 1, 5], [0, 5, 4]
  ];
  return { vertices: vertices, faces: faces };
}

function triPoints(geometry, face) {
  var v = geometry.vertices;
  if (typeof face[0] === 'number') return [v[face[0]], v[face[1]], v[face[2]]];
  return [face[0], face[1], face[2]];
}

function meshCenter(geometry) {
  var v = geometry.vertices;
  var lo = [Infinity, Infinity, Infinity];
  var hi = [-Infinity, -Infinity, -Infinity];
  for (var i = 0; i < v.length; i++) {
    for (var k = 0; k < 3; k++) {
      if (v[i][k] < lo[k]) lo[k] = v[i][k];
      if (v[i][k] > hi[k]) hi[k] = v[i][k];
    }
  }
  return [(lo[0] + hi[0]) / 2, (lo[1] + hi[1]) / 2, (lo[2] + hi[2]) / 2];
}

function audit(geometry) {
  if (!geometry || !Array.isArray(geometry.vertices) || !Array.isArray(geometry.faces)) {
    throw new TypeError('audit(geometry) expects { vertices: number[][], faces: number[][] }');
  }
  var c = meshCenter(geometry);
  var total = geometry.faces.length;
  var inward = 0;
  for (var i = 0; i < total; i++) {
    var p = triPoints(geometry, geometry.faces[i]);
    var n = cross(sub(p[1], p[0]), sub(p[2], p[0]));
    var centroid = [
      (p[0][0] + p[1][0] + p[2][0]) / 3,
      (p[0][1] + p[1][1] + p[2][1]) / 3,
      (p[0][2] + p[1][2] + p[2][2]) / 3
    ];
    var ref = sub(centroid, c);
    if (dot(n, ref) < 0) inward++;
  }
  return {
    faces: total,
    inwardFaces: inward,
    facesOutwardRatio: total === 0 ? 1 : (total - inward) / total
  };
}

function main() {
