function parseLine(line) {
  const fields = [];
  let cur = "", quoted = false, inQ = false;
  for (let i = 0; i < line.length; i++) {
    const c = line[i];
    if (inQ) {
      if (c === '"') { if (line[i + 1] === '"') { cur += '"'; i++; } else inQ = false; }
      else cur += c;
    } else if (c === '"') { inQ = true; quoted = true; }
    else if (c === ",") { fields.push({ v: cur, q: quoted }); cur = ""; quoted = false; }
    else cur += c;
  }
  fields.push({ v: cur, q: quoted });
  return fields;
}

